{"file_path":"src/diff.js","content":"/**
 * Longest-common-subsequence alignment between a side's lines and the base's
 * lines, using the tie-break rule from the specification: at each
 * disagreement, advance the side whose remaining subsequence is at least as
 * long as the other's, preferring to advance the base when they tie.
 */

/**
 * @param {string[]} side - this side's lines (mine or theirs)
 * @param {string[]} base - the base's lines
 * @returns {Array<[number, number]>} matched index pairs [sideIndex, baseIndex], in order
 */
export function computeMatches(side, base) {
  const n = side.length
  const m = base.length
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = side[i] === base[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advanceBase = dp[i][j + 1] >= dp[i + 1][j]
      if (advanceBase) j++
      else i++
    }
  }
  return matches
}

/**
 * Turns an alignment into the runs of base lines it does not cover, each
 * paired with the run of side lines that replaces it.
 *
 * @param {string[]} side
 * @param {string[]} base
 * @param {Array<[number, number]>} matches
 * @returns {Array<{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}>}
 */
export function computeChanges(side, base, matches) {
  const changes = []
  let prevSide = 0
  let prevBase = 0
  for (const [si, bi] of matches) {
    if (si > prevSide || bi > prevBase) {
      changes.push({ baseStart: prevBase, baseEnd: bi, sideStart: prevSide, sideEnd: si })
    }
    prevSide = si + 1
    prevBase = bi + 1
  }
  if (prevSide < side.length || prevBase < base.length) {
    changes.push({ baseStart: prevBase, baseEnd: base.length, sideStart: prevSide, sideEnd: side.length })
  }
  return changes
}
"}

