function linesEqual(array, other) {
  if (array.length !== other.length) return false
  for (let i = 0; i < array.length; i++) {
    if (array[i] !== other[i]) return false
  }
  return true
}

/**
 * Concatenates the lines a side contributes to a region: its own replacement
 * runs, and the base lines in between and around them that the side left
 * untouched.
 *
 * @param {string[]} base
 * @param {number} regionStart
 * @param {number} regionEnd
 * @param {Array<{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}>} sideChanges
 * @param {string[]} sideLines
 */
function assembleSideLines(base, regionStart, regionEnd, sideChanges, sideLines) {
  const result = []
  let pos = regionStart
  for (const change of sideChanges) {
    if (change.baseStart > pos) result.push(...base.slice(pos, change.baseStart))
    result.push(...sideLines.slice(change.sideStart, change.sideEnd))
    pos = change.baseEnd
  }
  if (pos < regionEnd) result.push(...base.slice(pos, regionEnd))
  return result
}

/**
 * Splits the base into stable stretches and regions touched by one or more
 * changes, and resolves each touched region against the given side.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = computeChanges(mine, base, computeMatches(mine, base)).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(theirs, base, computeMatches(theirs, base)).map(c => ({ ...c, side: 'theirs' }))
  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let baseCursor = 0
  let idx = 0
  while (idx < allChanges.length) {
    let regionStart = allChanges[idx].baseStart
    let regionEnd = allChanges[idx].baseEnd
    const regionChanges = [allChanges[idx]]
    idx++
    while (idx < allChanges.length && allChanges[idx].baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, allChanges[idx].baseEnd)
      regionChanges.push(allChanges[idx])
      idx++
    }

    if (regionStart > baseCursor) {
      regions.push({ kind: 'stable', lines: base.slice(baseCursor, regionStart) })
    }

    const mineCs = regionChanges.filter(c => c.side === 'mine')
    const theirsCs = regionChanges.filter(c => c.side === 'theirs')
    const baseLines = base.slice(regionStart, regionEnd)
    const mineLines = assembleSideLines(base, regionStart, regionEnd, mineCs, mine)
    const theirsLines = assembleSideLines(base, regionStart, regionEnd, theirsCs, theirs)

    let resolution
    if (linesEqual(mineLines, theirsLines)) {
      const kind = mineCs.length > 0 && theirsCs.length > 0 ? 'both' : mineCs.length > 0 ? 'mine' : 'theirs'
      resolution = { kind, lines: mineLines }
    } else if (linesEqual(mineLines, baseLines)) {
      resolution = { kind: 'theirs', lines: theirsLines }
    } else if (linesEqual(theirsLines, baseLines)) {
      resolution = { kind: 'mine', lines: mineLines }
    } else {
      resolution = { kind: 'conflict', mineLines, baseLines, theirsLines }
    }

    regions.push(resolution)
    baseCursor = regionEnd
  }

  if (baseCursor < base.length) {
    regions.push({ kind: 'stable', lines: base.slice(baseCursor, base.length) })
  }

  return regions
}
"}

