    const theirsCs = regionChanges.filter(c => c.side === 'theirs')
    const baseLines = base.slice(regionStart, regionEnd)
    const mineLines = assembleSideLines(base, regionStart, regionEnd, mineCs, mine)
    const theirsLines = assembleSideLines(base, regionStart, regionEnd, theirsCs, theirs)

