    } else if (linesEqual(mineLines, baseLines)) {
      resolution = { kind: 'theirs', lines: theirsLines }
    } else if (linesEqual(theirsLines, baseLines)) {
      resolution = { kind: 'mine', lines: mineLines }
    } else {
