import { readFileSync } from 'node:fs'
import { parseInput } from './input.js'
import { buildRegions } from './regions.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatMerge(regions, includeBase) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine')
      out.push(...region.mineLines)
      if (includeBase) {
        out.push('||||||| base')
        out.push(...region.baseLines)
      }
      out.push('=======')
      out.push(...region.theirsLines)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflict }
}

function formatRegions(regions) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      out.push(`${region.kind} ${region.lines.length}`)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflict }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !['merge', 'merge2', 'regions'].includes(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const text = readFileSync(0, 'utf8')

  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseInput(text)
  } catch (err) {
    fail(err.message)
    return
  }

  const regions = buildRegions(mine, base, theirs)
  const { text: output, conflict } =
    mode === 'regions' ? formatRegions(regions) : formatMerge(regions, mode === 'merge')

  process.stdout.write(output)
  process.exit(conflict ? 1 : 0)
}

main()
